"""Remove duplicates from a sequence."""


def unique(items):
    """Return `items` without duplicates, first occurrence first."""
    result = []
    seen = []
    for item in items:
        if item not in seen:
            seen.append(item)
            result.append(item)
    return result

args.new_string:
def test_keeps_first_occurrence_order():
    assert unique(["b", "a", "b", "c"]) == ["b", "a", "c"]


def test_works_with_unhashable_items():
    assert unique([{"a": 1}, {"a": 1}, {"b": 2}]) == [{"a": 1}, {"b": 2}]
